return [
    'tim-mach' => ['overview' => 'Bệnh tim mạch là nhóm bệnh ảnh hưởng đến tim và mạch máu. Mức độ và cách điều trị rất khác nhau giữa từng người.', 'symptoms' => ['Đau hoặc nặng ngực', 'Khó thở, mệt bất thường', 'Hồi hộp, choáng hoặc phù chân'], 'risk_factors' => ['Tăng huyết áp, mỡ máu hoặc đường huyết cao', 'Hút thuốc, ít vận động, thừa cân', 'Tiền sử gia đình'], 'monitoring' => ['Huyết áp, mỡ máu và đường huyết', 'Cân nặng, mức vận động và triệu chứng', 'Lịch khám tim mạch theo bác sĩ'], 'daily' => ['Dùng thuốc đúng giờ, không tự ngừng thuốc', 'Ăn giảm muối, vận động theo khả năng', 'Ghi lại triệu chứng bất thường'], 'urgent' => ['Đau ngực dữ dội hoặc kéo dài', 'Khó thở đột ngột, vã mồ hôi', 'Yếu liệt một bên, méo miệng, nói khó'], 'source' => 'https://www.who.int/health-topics/cardiovascular-diseases/'],
    'tieu-duong' => ['overview' => 'Tiểu đường là bệnh mạn tính làm đường huyết tăng kéo dài. Kiểm soát tốt giúp giảm nguy cơ ảnh hưởng đến tim, mắt, thận và thần kinh.', 'symptoms' => ['Khát và tiểu nhiều', 'Mệt mỏi, nhìn mờ', 'Vết thương lâu lành hoặc tê bì chân tay'], 'risk_factors' => ['Thừa cân, ít vận động', 'Gia đình có người mắc bệnh', 'Tăng huyết áp hoặc từng tiểu đường thai kỳ'], 'monitoring' => ['Đường huyết theo kế hoạch', 'Mắt, thận, bàn chân và huyết áp', 'HbA1c theo lịch bác sĩ'], 'daily' => ['Không tự bỏ bữa hoặc tự đổi thuốc', 'Kiểm tra bàn chân, chăm sóc da', 'Chuẩn bị cách xử trí hạ đường huyết theo hướng dẫn'], 'urgent' => ['Lơ mơ, co giật hoặc không thể ăn uống', 'Khó thở, nôn nhiều, đau bụng', 'Đường huyết bất thường không cải thiện'], 'source' => 'https://www.who.int/news-room/fact-sheets/detail/diabetes'],
    'tang-huyet-ap' => ['overview' => 'Tăng huyết áp là tình trạng áp lực trong mạch máu cao dai dẳng. Nhiều người không có triệu chứng, vì vậy đo huyết áp đúng cách rất quan trọng.', 'symptoms' => ['Thường không có dấu hiệu rõ', 'Có thể đau đầu, chóng mặt hoặc hồi hộp', 'Triệu chứng nặng có thể liên quan biến cố tim mạch'], 'risk_factors' => ['Tuổi, tiền sử gia đình', 'Ăn nhiều muối, ít vận động, thừa cân', 'Bệnh thận, tiểu đường hoặc stress'], 'monitoring' => ['Đo huyết áp ở thời điểm cố định', 'Ghi lại số đo và triệu chứng', 'Kiểm tra thận, tim và mắt theo chỉ định'], 'daily' => ['Dùng thuốc đều, không tự ngừng', 'Giảm muối và thực phẩm chế biến sẵn', 'Đo lại khi có triệu chứng bất thường'], 'urgent' => ['Đau ngực hoặc khó thở', 'Đau đầu dữ dội kèm yếu liệt/nói khó', 'Nhìn mờ hoặc lú lẫn đột ngột'], 'source' => 'https://www.who.int/health-topics/hypertension'],
    'mo-mau' => ['overview' => 'Mỡ máu cao là sự thay đổi bất lợi của cholesterol hoặc triglyceride. Bệnh thường không gây triệu chứng nhưng có thể làm tăng nguy cơ tim mạch.', 'symptoms' => ['Thường không có triệu chứng', 'Có thể phát hiện qua xét nghiệm máu', 'Biến cố tim mạch là dấu hiệu nghiêm trọng'], 'risk_factors' => ['Chế độ ăn nhiều chất béo bão hòa', 'Thừa cân, ít vận động', 'Di truyền, tiểu đường hoặc bệnh tuyến giáp'], 'monitoring' => ['Xét nghiệm mỡ máu theo lịch', 'Cân nặng, huyết áp và đường huyết', 'Đánh giá nguy cơ tim mạch tổng thể'], 'daily' => ['Ăn thêm rau, đậu và chất xơ', 'Vận động đều đặn theo khả năng', 'Dùng thuốc nếu được kê, không tự bỏ'], 'urgent' => ['Đau ngực, khó thở, vã mồ hôi', 'Yếu liệt hoặc nói khó đột ngột'], 'source' => 'https://www.who.int/health-topics/cardiovascular-diseases/'],
    'than-man' => ['overview' => 'Bệnh thận mạn tiến triển khi thận giảm khả năng lọc chất thải và dịch thừa. Chế độ ăn phụ thuộc giai đoạn bệnh, xét nghiệm và việc có lọc máu hay không.', 'symptoms' => ['Giai đoạn sớm có thể không rõ triệu chứng', 'Phù, mệt, thay đổi lượng nước tiểu', 'Buồn nôn hoặc ngứa khi bệnh nặng'], 'risk_factors' => ['Tiểu đường và tăng huyết áp', 'Bệnh thận hoặc tim mạch', 'Một số thuốc và tiền sử gia đình'], 'monitoring' => ['Creatinine/eGFR và xét nghiệm nước tiểu', 'Kali, natri, phốt pho theo chỉ định', 'Cân nặng, phù và lượng nước tiểu'], 'daily' => ['Không tự áp dụng chế độ nhiều đạm hoặc nhiều nước', 'Không tự dùng thuốc bổ, thuốc nam', 'Tuân thủ lịch xét nghiệm và lọc máu nếu có'], 'urgent' => ['Khó thở, phù tăng nhanh', 'Đau ngực, lơ mơ hoặc yếu nhiều', 'Tiểu rất ít hoặc không tiểu'], 'source' => 'https://www.who.int/news-room/fact-sheets/detail/kidney-disease'],
    'gout' => ['overview' => 'Gút liên quan đến tình trạng acid uric tăng và các đợt viêm khớp cấp. Việc điều trị cần phối hợp thuốc, ăn uống và theo dõi xét nghiệm.', 'symptoms' => ['Đau dữ dội, sưng nóng đỏ một khớp', 'Thường gặp ở ngón chân cái nhưng không chỉ ở đó', 'Đợt đau có thể tái phát'], 'risk_factors' => ['Tiền sử gia đình, bệnh thận', 'Rượu bia, thừa cân', 'Một số thuốc hoặc chế độ ăn đặc thù'], 'monitoring' => ['Acid uric theo chỉ định', 'Số lần và vị trí các đợt đau', 'Chức năng thận và thuốc đang dùng'], 'daily' => ['Uống nước theo hướng dẫn', 'Không tự ngừng thuốc hạ acid uric', 'Giảm rượu bia và đồ uống có đường'], 'urgent' => ['Sốt kèm khớp sưng nóng đỏ', 'Đau dữ dội không giảm hoặc không thể vận động', 'Tiểu rất ít hoặc đau hông lưng'], 'source' => 'https://www.who.int/health-topics/noncommunicable-diseases'],
    'gan-nhiem-mo' => ['overview' => 'Gan nhiễm mỡ là tình trạng mỡ tích tụ trong gan. Nguyên nhân có thể liên quan chuyển hóa, rượu bia hoặc thuốc nên cần đánh giá cụ thể.', 'symptoms' => ['Thường không có triệu chứng', 'Mệt hoặc khó chịu vùng bụng phải', 'Xét nghiệm men gan hoặc siêu âm bất thường'], 'risk_factors' => ['Thừa cân, tiểu đường, mỡ máu cao', 'Uống rượu bia', 'Ít vận động hoặc ăn dư năng lượng'], 'monitoring' => ['Men gan và xét nghiệm chuyển hóa', 'Siêu âm hoặc kiểm tra chuyên khoa khi cần', 'Cân nặng và vòng eo'], 'daily' => ['Giảm cân từ từ nếu bác sĩ khuyến nghị', 'Hạn chế rượu bia, nước ngọt', 'Ăn vừa đủ và vận động đều'], 'urgent' => ['Vàng da, lơ mơ hoặc chảy máu bất thường', 'Đau bụng dữ dội hoặc nôn kéo dài', 'Bụng to nhanh hoặc phù tăng'], 'source' => 'https://www.who.int/health-topics/noncommunicable-diseases'],
    'da-day' => ['overview' => 'Đau hoặc viêm dạ dày có nhiều nguyên nhân. Cần khám khi triệu chứng kéo dài để tìm nguyên nhân và dùng thuốc đúng.', 'symptoms' => ['Đau hoặc nóng rát vùng thượng vị', 'Đầy bụng, buồn nôn', 'Ợ hơi hoặc ăn nhanh no'], 'risk_factors' => ['H. pylori, thuốc giảm đau chống viêm', 'Rượu bia, hút thuốc', 'Bữa ăn thất thường hoặc yếu tố kích thích'], 'monitoring' => ['Mức độ đau, nôn và khả năng ăn uống', 'Phân đen hoặc dấu hiệu mất máu', 'Kết quả xét nghiệm khi bác sĩ chỉ định'], 'daily' => ['Ăn đúng bữa, phần nhỏ nếu cần', 'Không tự dùng thuốc giảm đau kéo dài', 'Tránh yếu tố làm triệu chứng tăng'], 'urgent' => ['Nôn ra máu hoặc đi ngoài phân đen', 'Đau bụng dữ dội, choáng', 'Sụt cân hoặc khó nuốt kéo dài'], 'source' => 'https://www.who.int/health-topics/noncommunicable-diseases'],
    'trao-nguoc' => ['overview' => 'Trào ngược xảy ra khi dịch dạ dày đi ngược lên thực quản, gây khó chịu và đôi khi ảnh hưởng giấc ngủ.', 'symptoms' => ['Ợ nóng, ợ chua', 'Nóng rát sau xương ức', 'Ho hoặc khàn tiếng về đêm'], 'risk_factors' => ['Ăn quá no, nằm ngay sau ăn', 'Thừa cân, hút thuốc', 'Một số thức ăn hoặc thuốc kích triệu chứng'], 'monitoring' => ['Tần suất và thời điểm triệu chứng', 'Khả năng nuốt, cân nặng và giấc ngủ', 'Tái khám nếu không cải thiện'], 'daily' => ['Ăn phần nhỏ, không nằm ngay sau ăn', 'Kê cao đầu khi được hướng dẫn', 'Tránh tác nhân riêng của mỗi người'], 'urgent' => ['Đau ngực mới xuất hiện hoặc dữ dội', 'Khó nuốt tăng dần, nôn ra máu', 'Sụt cân không rõ nguyên nhân'], 'source' => 'https://www.who.int/health-topics/noncommunicable-diseases'],
    'tao-bon' => ['overview' => 'Táo bón là tình trạng đi tiêu khó, thưa hoặc phân cứng. Nguyên nhân thường liên quan thói quen nhưng đôi khi cần loại trừ bệnh lý.', 'symptoms' => ['Phân cứng, rặn nhiều', 'Cảm giác đi chưa hết', 'Đầy bụng hoặc đau bụng nhẹ'], 'risk_factors' => ['Ít chất xơ, ít nước, ít vận động', 'Thay đổi sinh hoạt hoặc một số thuốc', 'Tuổi cao hoặc bệnh nền'], 'monitoring' => ['Số lần đi tiêu và hình dạng phân', 'Đau bụng, nôn hoặc chướng bụng', 'Mức đáp ứng khi thay đổi thói quen'], 'daily' => ['Tăng chất xơ từ từ', 'Uống đủ nước nếu không bị hạn chế', 'Đi bộ và không nhịn đi tiêu'], 'urgent' => ['Đau bụng dữ dội, nôn hoặc bụng trướng', 'Có máu trong phân hoặc sụt cân', 'Táo bón mới xuất hiện kéo dài ở người lớn tuổi'], 'source' => 'https://www.who.int/news-room/fact-sheets/detail/healthy-diet'],
    'beo-phi' => ['overview' => 'Thừa cân và béo phì là tình trạng tích tụ mỡ quá mức có thể ảnh hưởng đến tim mạch, chuyển hóa, khớp và chất lượng sống.', 'symptoms' => ['Tăng cân hoặc vòng eo tăng', 'Dễ mệt khi vận động', 'Ngáy to hoặc buồn ngủ ban ngày ở một số người'], 'risk_factors' => ['Năng lượng nạp vào cao hơn nhu cầu', 'Ít vận động, thiếu ngủ', 'Di truyền, thuốc và môi trường sống'], 'monitoring' => ['Cân nặng, vòng eo và huyết áp', 'Đường huyết, mỡ máu theo chỉ định', 'Khả năng vận động và giấc ngủ'], 'daily' => ['Đặt mục tiêu nhỏ, tránh nhịn ăn cực đoan', 'Tăng vận động phù hợp', 'Theo dõi khẩu phần và đồ uống có đường'], 'urgent' => ['Khó thở nhiều, đau ngực', 'Ngất hoặc phù tăng nhanh', 'Triệu chứng bất thường khi tập luyện'], 'source' => 'https://www.who.int/health-topics/obesity'],
    'loang-xuong' => ['overview' => 'Loãng xương làm xương yếu và dễ gãy hơn. Bệnh có thể diễn tiến âm thầm cho đến khi xảy ra gãy xương.', 'symptoms' => ['Thường không có triệu chứng sớm', 'Đau lưng hoặc giảm chiều cao', 'Gãy xương sau va chạm nhẹ'], 'risk_factors' => ['Tuổi cao, mãn kinh hoặc tiền sử gia đình', 'Thiếu canxi/vitamin D, ít vận động', 'Hút thuốc, rượu bia hoặc dùng một số thuốc'], 'monitoring' => ['Mật độ xương khi được chỉ định', 'Tiền sử té ngã và gãy xương', 'Canxi, vitamin D theo tư vấn'], 'daily' => ['Phòng ngã trong nhà', 'Vận động chịu sức nặng phù hợp', 'Không tự dùng liều cao thực phẩm bổ sung'], 'urgent' => ['Đau dữ dội sau té ngã', 'Không thể đứng hoặc cử động chi', 'Tê yếu bất thường'], 'source' => 'https://www.who.int/news-room/fact-sheets/detail/healthy-diet'],
    'thieu-mau' => ['overview' => 'Thiếu máu là tình trạng cơ thể không có đủ hồng cầu hoặc hemoglobin để vận chuyển oxy. Thiếu sắt chỉ là một trong nhiều nguyên nhân.', 'symptoms' => ['Mệt, yếu, da nhợt', 'Chóng mặt hoặc khó thở khi gắng sức', 'Tim đập nhanh hoặc đau đầu'], 'risk_factors' => ['Ăn thiếu sắt, mất máu hoặc hấp thu kém', 'Bệnh mạn tính, thai kỳ hoặc nhu cầu tăng', 'Một số bệnh cần được xét nghiệm tìm nguyên nhân'], 'monitoring' => ['Công thức máu và xét nghiệm sắt khi cần', 'Mức độ mệt, khó thở và chóng mặt', 'Đáp ứng với điều trị được kê'], 'daily' => ['Ăn đa dạng, kết hợp nguồn sắt và vitamin C', 'Không tự uống sắt liều cao', 'Tái khám nếu thiếu máu tái diễn'], 'urgent' => ['Khó thở khi nghỉ, đau ngực hoặc ngất', 'Chảy máu nhiều', 'Mệt tăng nhanh hoặc tim đập rất nhanh'], 'source' => 'https://www.who.int/news-room/fact-sheets/detail/healthy-diet'],
